"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"
import { XIcon } from "lucide-react"

const bannerVariants = cva("py-2.5 relative flex items-center", {
  variants: {
    variant: {
      default: "bg-foreground text-background w-full",
      floating:
        "my-2 rounded-4xl border bg-background mx-auto w-[calc(100%-2*var(--gutter,--spacing(4)))] max-w-[calc(var(--container,var(--container-7xl))-2*var(--gutter,--spacing(4)))] overflow-hidden",
    },
  },
  defaultVariants: {
    variant: "default",
  },
})

const BannerContext = React.createContext<(() => void) | null>(null)

// A closed banner stays closed for the browser session when it has a storage key.
const storageToken = (key: string) => `banner:${key}`
const subscribe = () => () => {}

function Banner({
  className,
  variant = "default",
  storageKey,
  hidden,
  ...props
}: React.ComponentProps<"aside"> &
  VariantProps<typeof bannerVariants> & {
    storageKey?: string
  }) {
  const [closed, setClosed] = React.useState(false)
  // The server renders the banner; the browser hides one closed earlier.
  const stored = React.useSyncExternalStore(
    subscribe,
    () =>
      storageKey != null &&
      sessionStorage.getItem(storageToken(storageKey)) === "hidden",
    () => false
  )

  const close = React.useCallback(() => {
    setClosed(true)
    if (storageKey) sessionStorage.setItem(storageToken(storageKey), "hidden")
  }, [storageKey])

  return (
    <BannerContext.Provider value={close}>
      <aside
        data-slot="banner"
        data-variant={variant}
        hidden={closed || stored || hidden}
        className={cn(bannerVariants({ variant }), className)}
        {...props}
      />
    </BannerContext.Provider>
  )
}

function BannerContainer({
  className,
  children,
  showClose = true,
  closeLabel = "Close",
  ...props
}: React.ComponentProps<"div"> & {
  showClose?: boolean
  closeLabel?: string
}) {
  const close = React.useContext(BannerContext)
  return (
    <div
      data-slot="banner-container"
      className={cn(
        "relative mx-auto flex w-full max-w-[var(--container,var(--container-7xl))] gap-4 px-[var(--gutter,--spacing(4))]",
        showClose && "pr-10",
        className
      )}
      {...props}
    >
      {children}
      {showClose && (
        <button
          type="button"
          data-slot="banner-close"
          aria-label={closeLabel}
          onClick={() => close?.()}
          className="rounded-full text-current/65 hover:text-current focus-visible:text-current focus-visible:ring-2 focus-visible:ring-ring/50 absolute top-1/2 right-4 z-20 inline-flex shrink-0 -translate-y-1/2 items-center justify-center transition-colors outline-none disabled:pointer-events-none disabled:opacity-50 in-[[data-variant=floating]]:right-5"
        >
          <XIcon className="size-4" />
          <span className="sr-only">{closeLabel}</span>
        </button>
      )}
    </div>
  )
}

export { Banner, BannerContainer, bannerVariants }
